#include <linux/module.h>
#include <net/tcp.h>

struct llm_cc {
    u32 min_rtt;
};

static void llm_init(struct sock *sk)
{
    struct llm_cc *ca = inet_csk_ca(sk);
    ca->min_rtt = 0x7fffffff;
}

static u32 llm_ssthresh(struct sock *sk)
{
    const struct tcp_sock *tp = tcp_sk(sk);
    return max(tp->snd_cwnd >> 1, 2U);
}

static void llm_cong_avoid(struct sock *sk, u32 ack, u32 acked)
{
    struct tcp_sock *tp = tcp_sk(sk);
    struct llm_cc *ca = inet_csk_ca(sk);
    u32 rtt = tp->srtt_us >> 3;

    if (!tcp_is_cwnd_limited(sk))
        return;

    if (rtt < ca->min_rtt)
        ca->min_rtt = rtt;

    if (tcp_in_slow_start(tp)) {
        tcp_slow_start(tp, acked);
    } else {
        if (rtt > ca->min_rtt + 2000) {
            if (tp->snd_cwnd > 20)
                tp->snd_cwnd--;
        } else {
            if (tp->snd_cwnd < 1000) {
                tp->snd_cwnd_cnt += acked;
                if (tp->snd_cwnd_cnt >= tp->snd_cwnd) {
                    tp->snd_cwnd_cnt = 0;
                    tp->snd_cwnd++;
                }
            }
        }
    }
}

static u32 llm_undo_cwnd(struct sock *sk)
{
    const struct tcp_sock *tp = tcp_sk(sk);
    return max(tp->snd_cwnd, tp->prior_cwnd);
}

static struct tcp_congestion_ops llm_cc_ops = {
    .init = llm_init,
    .ssthresh = llm_ssthresh,
    .cong_avoid = llm_cong_avoid,
    .undo_cwnd = llm_undo_cwnd,
    .name = "llm_cc",
    .owner = THIS_MODULE,
};

static int __init llm_cc_register(void)
{
    return tcp_register_congestion_control(&llm_cc_ops);
}

static void __exit llm_cc_unregister(void)
{
    tcp_unregister_congestion_control(&llm_cc_ops);
}

module_init(llm_cc_register);
module_exit(llm_cc_unregister);
MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("LLM-based Delay-Aware Congestion Control");
